}
void modifyArray(int* array) {
  *(array + 1) = 10;
  *(array + 3) = 20;
}
int main() {
  int i = 0, sum = 0, size = 5;
  int* array = (int*)malloc(size * sizeof(int));
  for (i = 0; i < size; i++) array[i] = i;
  processArray(array, size);
  modifyArray(array);
  for (i = 0; i < size; i++) sum += array[i];
  free(array);
  printf("Sum: %d\n", sum);
  return 0;
}

